// ---- Oeffentliche Profile (/u/<name>)
const LEVEL_NAMES = ["Neuling", "Anfänger", "Entdecker", "Kenner", "Profi", "Experte", "Meister", "Champion", "Legende", "⭐ SkyMaster"];
const FRAME_CSS = ["", "#9e9e9e,#e0e0e0,#9e9e9e", "#2ecc71,#8bf5b4,#2ecc71", "#2d8cff,#7fd3ff,#2d8cff", "#8e44ff,#d08cff,#8e44ff", "#ff8a00,#ffd166,#ff8a00", "#e53935,#ffc107,#e53935", "#00e5ff,#ff00e5,#00e5ff", "#ffc400,#fff59d,#ffa000,#ffc400", "#ff3b3b,#ffb300,#3ddc84,#2d8cff,#b44cff,#ff3b3b"];
const PROFILE_PER_DAY = 60;
const escH = s => String(s ?? "").replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const cleanS = (s, max) => String(s ?? "").replace(/[\r\n\t]+/g, " ").replace(/ {2,}/g, " ").trim().slice(0, max);
function cleanProfile(b, now) {
  const level = Math.max(0, Math.min(9, Math.trunc(Number(b.level) || 0)));
  const frame = Math.max(0, Math.min(9, Math.trunc(Number(b.frame) || 0)));
  const av = String(b.avatar || "").trim();
  const stats = Array.isArray(b.stats) ? b.stats.filter(x => Array.isArray(x) && x.length === 2).slice(0, 6).map(x => [cleanS(x[0], 24), cleanS(x[1], 24)]).filter(x => x[0] && x[1]) : [];
  const out = { name: cleanS(b.name, 40) || "SkyManager-Nutzer", title: cleanS(b.title, 40), bio: cleanS(b.bio, 200), avatar: av.length <= 8 && !av.includes("/") ? av : "", level, frame: frame <= level ? frame : 0, xp: Math.max(0, Math.trunc(Number(b.xp) || 0)), streak: Math.max(0, Math.trunc(Number(b.streak) || 0)), stats, updated: now };
  if (b.playing && typeof b.playing === "object" && cleanS(b.playing.g, 40)) { const st = Number(b.playing.s) || 0; if (st > 0 && st <= now + 60000 && now - st < 6 * 3600000) out.playing = { g: cleanS(b.playing.g, 40), s: st }; }
  return out;
}
function durText(ms) { const m = Math.max(0, Math.floor(ms / 60000)); return m < 60 ? m + " Min" : Math.floor(m / 60) + " Std " + (m % 60) + " Min"; }
function profilePage(user, p, origin, now, im) {
  im = im || {};
  const lvl = LEVEL_NAMES[p.level] || LEVEL_NAMES[0];
  const ring = p.frame > 0 ? `background:conic-gradient(${FRAME_CSS[p.frame]});padding:5px` : "background:#1b241f;padding:2px";
  const desc = [lvl + (p.title ? " · " + p.title : ""), ...p.stats.map(s => s[0] + ": " + s[1])].join(" · ");
  const playing = p.playing && now - p.playing.s < 6 * 3600000 ? `<div class="play">🎮 Spielt gerade <b>${escH(p.playing.g)}</b> · seit ${escH(durText(now - p.playing.s))}</div>` : "";
  return `<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<title>${escH(p.name)} · SkyManager</title>
<meta property="og:type" content="profile"><meta property="og:site_name" content="SkyManager"><meta property="og:title" content="${escH((p.avatar ? p.avatar + " " : "") + p.name)}"><meta property="og:description" content="${escH(desc)}"><meta property="og:image" content="${escH(origin)}${im.a ? "/u/" + escH(user) + "/avatar.jpg?v=" + escH(im.a) : "/app/icon.png"}"><meta name="theme-color" content="#3ddc84"><meta name="robots" content="noindex">
<style>body{margin:0;background:#0b0f0d;color:#eef5f0;font:16px/1.4 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;display:flex;justify-content:center;padding:28px 14px}main{width:100%;max-width:440px}.card{background:#131a16;border:1px solid #26332b;border-radius:22px;padding:22px;text-align:center}.ring{width:112px;height:112px;border-radius:50%;margin:0 auto 12px;box-sizing:border-box;${ring}}.av{width:100%;height:100%;border-radius:50%;background:#1b241f;display:flex;align-items:center;justify-content:center;font-size:52px;overflow:hidden}.av img{width:100%;height:100%;object-fit:cover}.card{overflow:hidden}.banner{display:block;width:calc(100% + 44px);margin:-22px -22px 0;height:150px;object-fit:cover}.banner+.ring{margin-top:-56px;position:relative}.nobanner{height:0}h1{margin:4px 0;font-size:26px}.title{color:#3ddc84;font-weight:700}.lvl{color:#93a39a;margin-top:4px}.bio{margin-top:12px;color:#c9d6ce;font-style:italic}.play{margin-top:14px;background:#123622;border:1px solid #1f4d33;border-radius:14px;padding:10px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:16px}.st{background:#1b241f;border-radius:14px;padding:10px 4px}.st b{display:block;font-size:16px}.st span{font-size:11px;color:#93a39a}footer{text-align:center;margin-top:16px;font-size:13px;color:#93a39a}a{color:#3ddc84}</style></head>
<body><main><div class="card">${im.b ? `<img class="banner" src="/u/${escH(user)}/banner.jpg?v=${escH(im.b)}" alt="">` : ""}<div class="ring"><div class="av">${im.a ? `<img src="/u/${escH(user)}/avatar.jpg?v=${escH(im.a)}" alt="">` : escH(p.avatar || (p.name[0] || "?").toUpperCase())}</div></div>
<h1>${escH(p.name)}</h1>${p.title ? `<div class="title">${escH(p.title)}</div>` : ""}<div class="lvl">Level ${escH(lvl)} · ${p.xp} XP${p.streak ? " · " + p.streak + " Tage 🔥" : ""}</div>
${p.bio ? `<div class="bio">„${escH(p.bio)}“</div>` : ""}${playing}
${p.stats.length ? `<div class="grid">${p.stats.map(s => `<div class="st"><b>${escH(s[1])}</b><span>${escH(s[0])}</span></div>`).join("")}</div>` : ""}</div>
<footer>Profil aus <a href="${escH(origin)}/app">SkyManager</a> · @${escH(user)}</footer></main></body></html>`;
}
