function newCode() { const a = new Uint32Array(1); crypto.getRandomValues(a); return String(a[0] % 1000000).padStart(6, "0"); }
async function sendMail(env, to, code, purpose) {
  const f = env.MAIL_FETCH || fetch;
  const what = purpose === "register" ? "dein neues SkyManager-Konto" : "deine E-Mail-Adresse bei SkyManager";
  const text = "Hallo!\n\nDein Code für " + what + ": " + code + "\n\nEr gilt 15 Minuten. Wenn du das nicht warst, ignoriere diese Mail einfach.\n\nSkyManager";
  const html = '<div style="font-family:Arial,sans-serif;max-width:420px;margin:auto;padding:20px;color:#111"><h2 style="color:#1fa463">SkyManager</h2><p>Dein Code für ' + what + ':</p><p style="font-size:32px;font-weight:bold;letter-spacing:6px;margin:16px 0">' + code + '</p><p style="color:#555">Er gilt 15 Minuten. Wenn du das nicht warst, ignoriere diese Mail einfach.</p></div>';
  const r = await f("https://api.resend.com/emails", { method: "POST", headers: { authorization: "Bearer " + env.RESEND_KEY, "content-type": "application/json" }, body: JSON.stringify({ from: env.MAIL_FROM || MAIL_FROM, to: [to], subject: "Dein SkyManager-Code: " + code, text, html }) });
  return r.ok;
}
async function bump(env, key, max) { const n = Number((await env.SKY.get(key)) || 0); if (n >= max) return false; await env.SKY.put(key, String(n + 1), { expirationTtl: 2 * 86400 }); return true; }
/** Prueft einen Code. @return null wenn ok, sonst die Fehlermeldung. */
async function checkCode(env, purpose, eh, code, user) {
  const key = "ev:" + purpose + ":" + eh, raw = await env.SKY.get(key);
  if (!raw) return "Kein gültiger Code. Fordere einen neuen an.";
  const v = JSON.parse(raw);
  if (purpose === "link" && v.user !== user) return "Kein gültiger Code. Fordere einen neuen an.";
  if (v.tries >= CODE_TRIES) { await env.SKY.delete(key); return "Zu viele falsche Versuche. Fordere einen neuen Code an."; }
  if (!same(await sha256(String(code || "").trim() + ":" + eh), v.h)) { v.tries++; await env.SKY.put(key, JSON.stringify(v), { expirationTtl: CODE_TTL }); return "Code falsch"; }
  await env.SKY.delete(key);
  return null;
}

// ---- Online-Bestenlisten (Werte ausserhalb dieser Grenzen gelten als unrealistisch)
const LB = { cps: { min: 0.1, max: 25, low: false, dec: 1 }, aim: { min: 1, max: 2000, low: false }, typing: { min: 1, max: 300, low: false }, snake: { min: 1, max: 2000, low: false }, g2048: { min: 4, max: 1000000, low: false }, react: { min: 80, max: 2000, low: true } };
const LB_KEEP = 100, LB_SHOW = 50;
function lbValue(game, v) { const c = LB[game]; const n = Number(v); if (!c || !Number.isFinite(n) || n < c.min || n > c.max) return null; return c.dec ? Math.round(n * 10) / 10 : Math.round(n); }
function lbSort(game, list) { const low = LB[game].low; return list.sort((a, b) => (low ? a.v - b.v : b.v - a.v) || a.at - b.at); }
async function lbRemove(env, user) { for (const g of Object.keys(LB)) { const l = JSON.parse((await env.SKY.get("lb:" + g)) || "[]"); const f = l.filter(x => x.user !== user); if (f.length !== l.length) await env.SKY.put("lb:" + g, JSON.stringify(f)); } await env.SKY.delete("sc:" + user); }

const json = (obj, status = 200) => new Response(JSON.stringify(obj), { status, headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" } });
const err = (msg, status) => json({ ok: false, error: msg }, status);

function hex(buf) { return [...new Uint8Array(buf)].map(b => b.toString(16).padStart(2, "0")).join(""); }
function randHex(bytes) { const a = new Uint8Array(bytes); crypto.getRandomValues(a); return hex(a.buffer); }
async function sha256(s) { return hex(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(s))); }
function same(a, b) { // Vergleich in gleichbleibender Zeit
  if (typeof a !== "string" || typeof b !== "string" || a.length !== b.length) return false;
  let r = 0; for (let i = 0; i < a.length; i++) r |= a.charCodeAt(i) ^ b.charCodeAt(i); return r === 0;
}
function lockSeconds(fails) { return fails < 5 ? 0 : Math.min(3600, 60 * 2 ** (fails - 5)); }

async function body(req, max = 64 * 1024) {
  const len = Number(req.headers.get("content-length") || 0);
  if (len > max) throw new Error("zu gross");
  const text = await req.text();
  if (text.length > max) throw new Error("zu gross");
  try { return JSON.parse(text || "{}"); } catch { throw new Error("kein JSON"); }
}

function b64urlBytes(s) {
  s = String(s).replace(/-/g, "+").replace(/_/g, "/");
  while (s.length % 4) s += "=";
  const bin = atob(s);
  return Uint8Array.from(bin, c => c.charCodeAt(0));
}
// ECDSA-Unterschrift: Java liefert DER, WebCrypto erwartet r||s (64 Byte). Beides wird angenommen.
function derToRaw(der) {
  if (der.length === 64) return der;
  if (der[0] !== 0x30) throw new Error("sig");
  let i = 2;
  if (der[1] & 0x80) i = 2 + (der[1] & 0x7f);
  const part = () => {
    if (der[i++] !== 0x02) throw new Error("sig");
    const len = der[i++];
    let v = der.slice(i, i + len); i += len;
    while (v.length > 32 && v[0] === 0) v = v.slice(1);
    if (v.length > 32) throw new Error("sig");
    const out = new Uint8Array(32); out.set(v, 32 - v.length); return out;
  };
  const r = part(), s = part();
  const raw = new Uint8Array(64); raw.set(r, 0); raw.set(s, 32); return raw;
}
async function adminOk(req, env, path, bodyText, now) {
  const ts = Number(req.headers.get("x-admin-ts") || 0), nonce = req.headers.get("x-admin-nonce") || "", sig = req.headers.get("x-admin-sig") || "";
  if (!ts || Math.abs(now - ts) > 300000 || !/^[0-9a-f]{32}$/.test(nonce) || !sig) return false;
  if (await env.SKY.get("n:" + nonce)) return false; // Wiederholung blockiert
  let raw, key;
  try {
    raw = derToRaw(b64urlBytes(sig));
    key = await crypto.subtle.importKey("spki", b64urlBytes(env.ADMIN_PUB || ADMIN_PUB_DEFAULT), { name: "ECDSA", namedCurve: "P-256" }, false, ["verify"]);
  } catch { return false; }
  const msg = req.method + "\n" + path + "\n" + ts + "\n" + nonce + "\n" + (await sha256(bodyText));
  const ok = await crypto.subtle.verify({ name: "ECDSA", hash: "SHA-256" }, key, raw, new TextEncoder().encode(msg));
  if (!ok) return false;
  await env.SKY.put("n:" + nonce, "1", { expirationTtl: 900 });
  return true;
}
async function deleteUserAll(env, user) {
  try { await lbRemove(env, user); } catch { }
  try { const u = JSON.parse((await env.SKY.get("u:" + user)) || "{}"); if (u.eh) await env.SKY.delete("e:" + u.eh); } catch { }
  const list = JSON.parse((await env.SKY.get("b:" + user)) || "[]");
  for (const x of list) await env.SKY.delete("d:" + user + ":" + x.id);
  for (const k of ["b:", "u:", "o:", "om:", "pp:"]) await env.SKY.delete(k + user);
  await deleteProfileImages(env, user);
  await env.SKY.delete("pw:" + user);
  try { const cl = JSON.parse((await env.SKY.get("c:" + user)) || "[]"); for (const c of cl) await env.SKY.delete("cd:" + user + ":" + c.id); await env.SKY.delete("c:" + user); } catch { }
}

async function userOf(req, env) {
  const h = req.headers.get("authorization") || "";
  const m = h.match(/^Bearer ([0-9a-f]{64})$/);
  if (!m) return null;
  const user = await env.SKY.get("t:" + m[1]);
  // Ein Token gilt nur, solange das Konto existiert (nach "Konto löschen" sind alle alten Tokens wertlos).
  if (!user || !(await env.SKY.get("u:" + user))) return null;
  return user;
}

export default {
  async fetch(req, env) {
    try {
      const url = new URL(req.url);
      const p = url.pathname.replace(/\/+$/, "");
      const now = Date.now();
      if (req.method === "GET" && (p === "" || p === "/")) return Response.redirect(url.origin + "/app", 302);
      if (req.method === "GET" && (p === "/app" || p.startsWith("/app/"))) return webAsset(p) || err("Nicht gefunden", 404);
      if (!env.SKY) return err("Server nicht eingerichtet: KV-Namespace 'SKY' fehlt", 500);
      const ui = p.match(/^\/u\/([A-Za-z0-9_.-]{3,24})\/(avatar|banner)\.jpg$/);
      if (ui && req.method === "GET") {
        const user = ui[1].toLowerCase(), ch = ui[2] === "avatar" ? "a" : "b";
        const data = (await env.SKY.get("pp:" + user)) ? await env.SKY.get("pi:" + user + ":" + ch) : null;
        const bytes = data ? b64bytes(data) : null, type = bytes ? imgType(bytes) : null;
        if (!type) return new Response("Nicht gefunden", { status: 404, headers: { "content-type": "text/plain; charset=utf-8" } });
        return new Response(bytes, { headers: { "content-type": type, "cache-control": "public, max-age=300", "content-security-policy": "default-src 'none'", "x-content-type-options": "nosniff" } });
      }
      const lbm = p.match(/^\/api\/leaderboard\/([a-z0-9]+)$/);
      if (lbm && req.method === "GET") {
        if (!LB[lbm[1]]) return err("Unbekannte Bestenliste", 404);
        const l = JSON.parse((await env.SKY.get("lb:" + lbm[1])) || "[]");
        const me = await userOf(req, env);
        const idx = me ? l.findIndex(x => x.user === me) : -1;
        return json({ ok: true, game: lbm[1], low: LB[lbm[1]].low, top: l.slice(0, LB_SHOW).map((x, i) => ({ rank: i + 1, name: x.name, v: x.v, me: x.user === me })), me: idx >= 0 ? { rank: idx + 1, v: l[idx].v } : null });
      }
      const um0 = p.match(/^\/(u|api\/u)\/([A-Za-z0-9_.-]{3,24})$/);
      if (um0 && req.method === "GET") {
        const user = um0[2].toLowerCase(), raw = await env.SKY.get("pp:" + user);
        if (um0[1] === "api/u") return raw ? json({ ok: true, user, profile: JSON.parse(raw) }) : err("Kein öffentliches Profil", 404);
        const hdr = { "content-type": "text/html; charset=utf-8", "content-security-policy": PAGE_CSP, "x-content-type-options": "nosniff", "referrer-policy": "no-referrer", "cache-control": "public, max-age=60" };
        if (!raw) return new Response(`<!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nicht gefunden</title><body style="background:#0b0f0d;color:#eef5f0;font-family:sans-serif;text-align:center;padding:60px 20px"><h1>Profil nicht gefunden</h1><p>Dieses Profil gibt es nicht oder es ist offline.</p></body></html>`, { status: 404, headers: hdr });
        return new Response(profilePage(user, JSON.parse(raw), url.origin, now, JSON.parse((await env.SKY.get("pim:" + user)) || "{}")), { headers: hdr });
      }

      if (p === "/api/health" && req.method === "GET") return json({ ok: true, app: "SkyManager-Cloud", version: VERSION, register: env.REGISTER_CODE ? "code" : "open", email: !!(env.RESEND_KEY && env.EMAIL_SECRET) });

      const mailReady = !!(env.RESEND_KEY && env.EMAIL_SECRET);
      if (p === "/api/email/code" && req.method === "POST") {
        const b = await body(req);
        if (!mailReady) return err("E-Mail ist auf dem Server nicht eingerichtet", 503);
        const purpose = b.purpose === "link" ? "link" : "register";
        const to = plainEmail(b.email), canon = canonEmail(b.email);
        if (!to || !canon) return err("Das ist keine gültige E-Mail-Adresse", 400);
        let who = null;
        if (purpose === "link") { who = await userOf(req, env); if (!who) return err("Nicht angemeldet", 401); }
        const eh = await hmacHex(env.EMAIL_SECRET, canon);
        const owner = await env.SKY.get("e:" + eh);
        if (owner) return err(owner === who ? "Diese E-Mail ist schon mit deinem Konto verbunden" : "Diese E-Mail gehört schon zu einem Konto", 409);
        const prev = JSON.parse((await env.SKY.get("ev:" + purpose + ":" + eh)) || "null");
        if (prev && now - prev.sent < CODE_COOLDOWN) return err("Bitte warte eine Minute, bevor du einen neuen Code anforderst", 429);
        const ip = req.headers.get("cf-connecting-ip") || "unbekannt", day = new Date(now).toISOString().slice(0, 10);
        if (!(await bump(env, "rm:" + eh + ":" + day, CODES_PER_EMAIL_DAY))) return err("Heute wurden schon genug Codes an diese Adresse geschickt", 429);
        if (!(await bump(env, "rq:" + ip + ":" + day, CODES_PER_IP_DAY))) return err("Von diesem Anschluss wurden heute schon genug Codes angefordert", 429);
        const code = newCode();
        await env.SKY.put("ev:" + purpose + ":" + eh, JSON.stringify({ h: await sha256(code + ":" + eh), tries: 0, sent: now, user: who }), { expirationTtl: CODE_TTL });
        if (!(await sendMail(env, to, code, purpose))) return err("Die E-Mail konnte nicht verschickt werden. Versuch es später nochmal.", 502);
        return json({ ok: true, to: maskEmail(to) });
      }

      if (p === "/api/register" && req.method === "POST") {
        const b = await body(req);
        const user = String(b.user || "").trim().toLowerCase();
        if (!USER_RE.test(user)) return err("Benutzername: 3 bis 24 Zeichen, nur a-z, 0-9, _ . -", 400);
        if (!HEX64.test(String(b.auth || ""))) return err("Ungültige Anmeldedaten", 400);
        if (env.REGISTER_CODE && !same(String(b.code || ""), String(env.REGISTER_CODE))) return err("Falscher Einladungscode", 403);
        if (await env.SKY.get("u:" + user)) return err("Benutzername ist schon vergeben", 409);
        let emailFields = {}, eh = null;
        if (mailReady && env.REQUIRE_EMAIL !== "off") {
          const to = plainEmail(b.email), canon = canonEmail(b.email);
          if (!to || !canon || !b.emailCode) return err("Für neue Konten brauchst du eine bestätigte E-Mail. Bitte aktualisiere SkyManager.", 400);
          eh = await hmacHex(env.EMAIL_SECRET, canon);
          if (await env.SKY.get("e:" + eh)) return err("Diese E-Mail gehört schon zu einem Konto", 409);
          const bad = await checkCode(env, "register", eh, b.emailCode, null);
          if (bad) return err(bad, 400);
          emailFields = { eh, em: await encEmail(env.EMAIL_SECRET, to), emMask: maskEmail(to), emAt: now };
        }
        const ip = req.headers.get("cf-connecting-ip") || "unbekannt";
        const regKey = "r:" + ip + ":" + new Date(now).toISOString().slice(0, 10);
        const regs = Number((await env.SKY.get(regKey)) || 0);
        if (regs >= REG_PER_IP_DAY) return err("Von diesem Anschluss wurden heute schon genug Konten erstellt. Bitte morgen wieder.", 429);
        await env.SKY.put(regKey, String(regs + 1), { expirationTtl: 2 * 86400 });
        const salt = randHex(16);
        await env.SKY.put("u:" + user, JSON.stringify({ salt, hash: await sha256(salt + ":" + b.auth), created: now, fails: 0, lockUntil: 0, ...emailFields }));
        if (eh) await env.SKY.put("e:" + eh, user);
        return json({ ok: true, user, email: emailFields.emMask || null });
      }

      if (p === "/api/login" && req.method === "POST") {
        const b = await body(req);
        const user = String(b.user || "").trim().toLowerCase();
        const raw = USER_RE.test(user) ? await env.SKY.get("u:" + user) : null;
        if (!raw || !HEX64.test(String(b.auth || ""))) return err("Benutzername oder Passwort falsch", 401);
        const u = JSON.parse(raw);
        if ((u.lockUntil || 0) > now) return err("Zu viele Fehlversuche. Bitte warte " + Math.ceil((u.lockUntil - now) / 1000) + " Sekunden.", 429);
        if (!same(await sha256(u.salt + ":" + b.auth), u.hash)) {
          u.fails = (u.fails || 0) + 1;
          const lock = lockSeconds(u.fails);
          u.lockUntil = lock ? now + lock * 1000 : 0;
          await env.SKY.put("u:" + user, JSON.stringify(u));
          return err("Benutzername oder Passwort falsch", 401);
        }
        if (u.fails) { u.fails = 0; u.lockUntil = 0; await env.SKY.put("u:" + user, JSON.stringify(u)); }
        const token = randHex(32);
        await env.SKY.put("t:" + token, user, { expirationTtl: TOKEN_TTL });
        return json({ ok: true, token, user });
      }

      // ---- Admin (signiert mit dem Schluessel aus dem Admin-Panel)
      if (p.startsWith("/api/admin/")) {
        const text = await req.text();
        if (text.length > 65536) return err("Anfrage zu groß", 400);
        if (!(await adminOk(req, env, url.pathname, text, now))) return err("Nicht berechtigt", 403);
        if (p === "/api/admin/users" && req.method === "GET") {
          const users = []; let cursor;
          do {
            const r = await env.SKY.list({ prefix: "u:", cursor });
            for (const k of r.keys) {
              const name = k.name.slice(2);
              const u = JSON.parse((await env.SKY.get(k.name)) || "{}");
              const bl = JSON.parse((await env.SKY.get("b:" + name)) || "[]");
              const om = JSON.parse((await env.SKY.get("om:" + name)) || "null");
              users.push({ user: name, email: u.emMask || null, created: u.created || 0, fails: u.fails || 0, locked: (u.lockUntil || 0) > now, backups: bl.length, size: bl.reduce((s, x) => s + (x.size || 0), 0), last: bl.length ? bl[0].created : 0, office: om });
            }
            cursor = r.list_complete ? null : r.cursor;
          } while (cursor && users.length < 5000);
          users.sort((a, b) => a.user.localeCompare(b.user));
          return json({ ok: true, users });
        }
        const um = p.match(/^\/api\/admin\/users\/([a-z0-9_.-]{3,24})(\/unlock)?$/);
        if (um) {
          const raw = await env.SKY.get("u:" + um[1]);
          if (!raw) return err("Benutzer nicht gefunden", 404);
          if (!um[2] && req.method === "DELETE") { await deleteUserAll(env, um[1]); return json({ ok: true }); }
          if (um[2] && req.method === "POST") { const u = JSON.parse(raw); u.fails = 0; u.lockUntil = 0; await env.SKY.put("u:" + um[1], JSON.stringify(u)); return json({ ok: true }); }
        }
        if (p === "/api/admin/office" && req.method === "GET") {
          const out = []; let cursor;
          do {
            const r = await env.SKY.list({ prefix: "om:", cursor });
            for (const k of r.keys) { const m = await env.SKY.get(k.name); if (m) out.push(JSON.parse(m)); }
            cursor = r.list_complete ? null : r.cursor;
          } while (cursor && out.length < 5000);
          out.sort((a, b) => b.updated - a.updated);
          return json({ ok: true, office: out });
        }
        const om = p.match(/^\/api\/admin\/office\/([a-z0-9_.-]{3,24})$/);
        if (om) {
          const meta = await env.SKY.get("om:" + om[1]);
          if (!meta) return err("Keine Büro-Daten von diesem Benutzer", 404);
          if (req.method === "GET") return json({ ok: true, office: JSON.parse(meta), blob: await env.SKY.get("o:" + om[1]) });
          if (req.method === "DELETE") { await env.SKY.delete("o:" + om[1]); await env.SKY.delete("om:" + om[1]); return json({ ok: true }); }
        }
        return err("Nicht gefunden", 404);
      }

      // ---- ab hier nur angemeldet
      const user = await userOf(req, env);
      if (!user) return err("Nicht angemeldet", 401);
      const listKey = "b:" + user;
      const list = JSON.parse((await env.SKY.get(listKey)) || "[]");

      if (p === "/api/logout" && req.method === "POST") {
        await env.SKY.delete("t:" + req.headers.get("authorization").slice(7));
        return json({ ok: true });
      }

      if (p === "/api/backups" && req.method === "GET") return json({ ok: true, backups: list });

      // ---- Aenderungen vom iPhone (verschluesselt, nur das Android-Handy kann sie lesen und uebernehmen)
      if (p === "/api/changes" && req.method === "POST") {
        const b = await body(req, 70 * 1024);
        const data = String(b.data || "");
        if (!data.startsWith("SKYB1_") || data.length > 64 * 1024 || !B64URL.test(data)) return err("Ungültige Änderung", 400);
        const cl = JSON.parse((await env.SKY.get("c:" + user)) || "[]");
        if (cl.length >= 50) return err("Zu viele offene Änderungen. Öffne SkyManager auf dem Android-Handy, dann werden sie übernommen.", 429);
        if (!(await bump(env, "qc:" + user + ":" + new Date(now).toISOString().slice(0, 10), 200))) return err("Heute schon genug Änderungen", 429);
        const id = randHex(8);
        await env.SKY.put("cd:" + user + ":" + id, data);
        cl.push({ id, created: now, size: data.length });
        await env.SKY.put("c:" + user, JSON.stringify(cl));
        return json({ ok: true, id });
      }
      if (p === "/api/changes" && req.method === "GET") {
        const cl = JSON.parse((await env.SKY.get("c:" + user)) || "[]"), out = [];
        for (const c of cl) { const d = await env.SKY.get("cd:" + user + ":" + c.id); if (d) out.push({ ...c, data: d }); }
        return json({ ok: true, changes: out });
      }
      const cm = p.match(/^\/api\/changes\/([0-9a-f]{16})$/);
      if (cm && req.method === "DELETE") {
        const cl = JSON.parse((await env.SKY.get("c:" + user)) || "[]");
        await env.SKY.delete("cd:" + user + ":" + cm[1]);
        await env.SKY.put("c:" + user, JSON.stringify(cl.filter(c => c.id !== cm[1])));
        return json({ ok: true });
      }

      if (p === "/api/scores" && req.method === "POST") {
        const b = await body(req, 8 * 1024);
        if (!(await bump(env, "qs:" + user + ":" + new Date(now).toISOString().slice(0, 10), 60))) return err("Heute schon oft genug hochgeladen", 429);
        const name = cleanS(b.name, 24) || "Spieler";
        const accepted = {}, rejected = [];
        for (const [g, raw] of Object.entries(b.scores || {})) {
          if (!LB[g]) continue;
          const v = lbValue(g, raw);
          if (v === null) { rejected.push(g); continue; }
          accepted[g] = v;
          const l = JSON.parse((await env.SKY.get("lb:" + g)) || "[]");
          const i = l.findIndex(x => x.user === user);
          const better = i < 0 || (LB[g].low ? v < l[i].v : v > l[i].v);
          if (i >= 0) { l[i].name = name; if (better) { l[i].v = v; l[i].at = now; } } else l.push({ user, name, v, at: now });
          await env.SKY.put("lb:" + g, JSON.stringify(lbSort(g, l).slice(0, LB_KEEP)));
        }
        const prevSc = JSON.parse((await env.SKY.get("sc:" + user)) || "null");
        if (prevSc && prevSc.name !== name) for (const g of Object.keys(LB)) {
          if (g in accepted) continue;
          const l = JSON.parse((await env.SKY.get("lb:" + g)) || "[]"), i = l.findIndex(x => x.user === user);
          if (i >= 0 && l[i].name !== name) { l[i].name = name; await env.SKY.put("lb:" + g, JSON.stringify(l)); }
        }
        await env.SKY.put("sc:" + user, JSON.stringify({ name, scores: { ...(prevSc ? prevSc.scores : {}), ...accepted }, updated: now }));
        return json({ ok: true, accepted, rejected });
      }
      if (p === "/api/scores" && req.method === "DELETE") { await lbRemove(env, user); return json({ ok: true }); }

      if (p === "/api/account" && req.method === "GET") {
        const u = JSON.parse((await env.SKY.get("u:" + user)) || "{}");
        return json({ ok: true, user, created: u.created || 0, email: u.emMask || null, emailReady: mailReady });
      }
      if (p === "/api/email/verify" && req.method === "POST") {
        if (!mailReady) return err("E-Mail ist auf dem Server nicht eingerichtet", 503);
        const b = await body(req);
        const to = plainEmail(b.email), canon = canonEmail(b.email);
        if (!to || !canon) return err("Das ist keine gültige E-Mail-Adresse", 400);
        const eh = await hmacHex(env.EMAIL_SECRET, canon);
        const owner = await env.SKY.get("e:" + eh);
        if (owner && owner !== user) return err("Diese E-Mail gehört schon zu einem Konto", 409);
        const bad = await checkCode(env, "link", eh, b.code, user);
        if (bad) return err(bad, 400);
        const u = JSON.parse(await env.SKY.get("u:" + user));
        if (u.eh && u.eh !== eh) await env.SKY.delete("e:" + u.eh);
        Object.assign(u, { eh, em: await encEmail(env.EMAIL_SECRET, to), emMask: maskEmail(to), emAt: now });
        await env.SKY.put("u:" + user, JSON.stringify(u));
        await env.SKY.put("e:" + eh, user);
        return json({ ok: true, email: u.emMask });
      }

      if (p === "/api/profile" && req.method === "PUT") {
        const b = await body(req, 16 * 1024);
        const qk = "qp:" + user + ":" + new Date(now).toISOString().slice(0, 10);
        const q = Number((await env.SKY.get(qk)) || 0);
        if (q >= PROFILE_PER_DAY) return err("Heute schon oft genug aktualisiert", 429);
        await env.SKY.put(qk, String(q + 1), { expirationTtl: 2 * 86400 });
        const prof = cleanProfile(b, now);
        await env.SKY.put("pp:" + user, JSON.stringify(prof));
        return json({ ok: true, profile: prof, url: url.origin + "/u/" + user });
      }
      if (p === "/api/profile" && req.method === "DELETE") { await env.SKY.delete("pp:" + user); await deleteProfileImages(env, user); await env.SKY.delete("pw:" + user); return json({ ok: true }); }
      if (p === "/api/profile" && req.method === "GET") {
        const raw = await env.SKY.get("pp:" + user);
        return json({ ok: true, user, online: !!raw, profile: raw ? JSON.parse(raw) : null, images: JSON.parse((await env.SKY.get("pim:" + user)) || "{}"), url: url.origin + "/u/" + user });
      }
      // Aenderungen aus dem Browser: nur Name, Titel, Bio, Emoji, Rahmen. Level, XP und Stats bleiben, wie die App sie gemeldet hat.
      if (p === "/api/profile/web" && (req.method === "PATCH" || req.method === "POST")) {
        const b = await body(req, 16 * 1024);
        const raw = await env.SKY.get("pp:" + user);
        const base = raw ? JSON.parse(raw) : cleanProfile({ name: b.name, level: 0 }, now);
        const qk = "qp:" + user + ":" + new Date(now).toISOString().slice(0, 10);
        const q = Number((await env.SKY.get(qk)) || 0);
        if (q >= PROFILE_PER_DAY) return err("Heute schon oft genug aktualisiert", 429);
        await env.SKY.put(qk, String(q + 1), { expirationTtl: 2 * 86400 });
        const ch = JSON.parse((await env.SKY.get("pw:" + user)) || "{}");
        const next = { ...base };
        if ("name" in b) { next.name = cleanS(b.name, 40) || "SkyManager-Nutzer"; ch.name = next.name; }
        if ("title" in b) { next.title = cleanS(b.title, 40); ch.title = next.title; }
        if ("bio" in b) { next.bio = cleanS(b.bio, 200); ch.bio = next.bio; }
        if ("avatar" in b) { const av = String(b.avatar || "").trim(); next.avatar = av.length <= 8 && !av.includes("/") ? av : ""; ch.avatar = next.avatar; }
        if ("frame" in b) { const fr = Math.max(0, Math.min(9, Math.trunc(Number(b.frame) || 0))); next.frame = fr <= (base.level || 0) ? fr : base.frame || 0; ch.frame = next.frame; }
        next.updated = now;
        ch.at = now;
        await env.SKY.put("pp:" + user, JSON.stringify(next));
        await env.SKY.put("pw:" + user, JSON.stringify(ch));
        return json({ ok: true, profile: next });
      }
      if (p === "/api/profile/changes" && req.method === "GET") return json({ ok: true, changes: JSON.parse((await env.SKY.get("pw:" + user)) || "null") });
      if (p === "/api/profile/changes" && req.method === "DELETE") {
        const b = await body(req);
        const ch = JSON.parse((await env.SKY.get("pw:" + user)) || "null");
        // Nur loeschen, was die App wirklich uebernommen hat (Stand "at"); neuere Aenderungen bleiben liegen
        if (ch && (!b.at || ch.at <= Number(b.at))) await env.SKY.delete("pw:" + user);
        return json({ ok: true });
      }
      const pim = p.match(/^\/api\/profile\/img\/(a|b)$/);
      if (pim && req.method === "PUT") {
        const b = await body(req, 1024 * 1024);
        const bytes = b64bytes(b.data);
        if (!bytes || !imgType(bytes)) return err("Nur JPEG- oder PNG-Bilder", 400);
        if (bytes.length > IMG_MAX[pim[1]]) return err("Bild zu groß", 400);
        const qk = "qp:" + user + ":" + new Date(now).toISOString().slice(0, 10);
        const q = Number((await env.SKY.get(qk)) || 0);
        if (q >= PROFILE_PER_DAY) return err("Heute schon oft genug aktualisiert", 429);
        await env.SKY.put(qk, String(q + 1), { expirationTtl: 2 * 86400 });
        await env.SKY.put("pi:" + user + ":" + pim[1], String(b.data));
        const meta = JSON.parse((await env.SKY.get("pim:" + user)) || "{}");
        meta[pim[1]] = (await sha256(String(b.data))).slice(0, 10);
        await env.SKY.put("pim:" + user, JSON.stringify(meta));
        if (b.src === "web") { const ch = JSON.parse((await env.SKY.get("pw:" + user)) || "{}"); ch.img = { ...(ch.img || {}), [pim[1]]: meta[pim[1]] }; ch.at = now; await env.SKY.put("pw:" + user, JSON.stringify(ch)); }
        return json({ ok: true, v: meta[pim[1]] });
      }
      if (pim && req.method === "DELETE") {
        await env.SKY.delete("pi:" + user + ":" + pim[1]);
        const meta = JSON.parse((await env.SKY.get("pim:" + user)) || "{}"); delete meta[pim[1]];
        await env.SKY.put("pim:" + user, JSON.stringify(meta));
        if (url.searchParams.get("src") === "web") { const ch = JSON.parse((await env.SKY.get("pw:" + user)) || "{}"); ch.img = { ...(ch.img || {}), [pim[1]]: "" }; ch.at = now; await env.SKY.put("pw:" + user, JSON.stringify(ch)); }
        return json({ ok: true });
      }

      if (p === "/api/office" && req.method === "PUT") {
        const b = await body(req, MAX_OFFICE + 4096);
        const blob = String(b.blob || "");
        if (blob.length > MAX_OFFICE || !OFFICE_RE.test(blob)) return err("Ungültige Büro-Daten", 400);
        const qk = "qo:" + user + ":" + new Date(now).toISOString().slice(0, 10);
        const q = Number((await env.SKY.get(qk)) || 0);
        if (q >= OFFICE_PER_DAY) return err("Heute schon genug Büro-Daten hochgeladen", 429);
        await env.SKY.put(qk, String(q + 1), { expirationTtl: 2 * 86400 });
        const meta = { user, name: String(b.name || "").slice(0, 40), role: b.role === "admin" ? "admin" : "buero", app: String(b.app || "").slice(0, 20), updated: now, size: blob.length };
        await env.SKY.put("o:" + user, blob);
        await env.SKY.put("om:" + user, JSON.stringify(meta));
        return json({ ok: true, office: meta });
      }
      if (p === "/api/office" && req.method === "DELETE") {
        await env.SKY.delete("o:" + user); await env.SKY.delete("om:" + user);
        return json({ ok: true });
      }

      if (p === "/api/backups" && req.method === "POST") {
        const b = await body(req, MAX_DATA + 4096);
        const data = String(b.data || "");
        if (!data || data.length > MAX_DATA || !B64URL.test(data)) return err("Ungültiges Backup", 400);
        const today = new Date(now).toISOString().slice(0, 10);
        const todayCount = list.filter(x => new Date(x.created).toISOString().slice(0, 10) === today).length;
        const upKey = "q:" + user + ":" + today;
        const ups = Number((await env.SKY.get(upKey)) || 0);
        if (Math.max(ups, todayCount) >= UPLOADS_PER_DAY) return err("Heute wurden schon " + UPLOADS_PER_DAY + " Backups hochgeladen. Morgen geht es weiter.", 429);
        await env.SKY.put(upKey, String(ups + 1), { expirationTtl: 2 * 86400 });
        const id = randHex(8);
        const meta = { id, created: now, size: data.length, app: String(b.app || "").slice(0, 20), note: String(b.note || "").slice(0, 60) };
        await env.SKY.put("d:" + user + ":" + id, data);
        list.unshift(meta);
        while (list.length > KEEP) { const old = list.pop(); await env.SKY.delete("d:" + user + ":" + old.id); }
        await env.SKY.put(listKey, JSON.stringify(list));
        return json({ ok: true, backup: meta });
      }

      const m = p.match(/^\/api\/backups\/([0-9a-f]+)$/);
      if (m) {
        const id = m[1];
        if (!ID_RE.test(id) || !list.some(x => x.id === id)) return err("Backup nicht gefunden", 404);
        if (req.method === "GET") {
          const data = await env.SKY.get("d:" + user + ":" + id);
          if (data == null) return err("Backup nicht gefunden", 404);
          return json({ ok: true, backup: list.find(x => x.id === id), data });
        }
        if (req.method === "DELETE") {
          await env.SKY.delete("d:" + user + ":" + id);
          await env.SKY.put(listKey, JSON.stringify(list.filter(x => x.id !== id)));
          return json({ ok: true });
        }
      }

      if (p === "/api/account" && req.method === "DELETE") {
        const b = await body(req);
        const u = JSON.parse((await env.SKY.get("u:" + user)) || "null");
        if (!u || !HEX64.test(String(b.auth || "")) || !same(await sha256(u.salt + ":" + b.auth), u.hash)) return err("Passwort falsch", 401);
        await deleteUserAll(env, user);
        await env.SKY.delete("t:" + req.headers.get("authorization").slice(7));
        return json({ ok: true });
      }

      return err("Nicht gefunden", 404);
    } catch (e) {
      return err(e && e.message === "zu gross" ? "Anfrage zu groß" : e && e.message === "kein JSON" ? "Ungültige Anfrage" : "Serverfehler", e && (e.message === "zu gross" || e.message === "kein JSON") ? 400 : 500);
    }
  },
};
